import { useState } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

type SignupValues = {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
};

type SignupWizardProps = {
  onSubmit: (values: SignupValues) => void;
};

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const emptyValues: SignupValues = {
  name: '',
  email: '',
  phone: '',
  city: '',
  street: '',
  zip: '',
};

const summaryLabels: Array<[keyof SignupValues, string]> = [
  ['name', 'Имя'],
  ['email', 'Электронная почта'],
  ['phone', 'Телефон'],
  ['city', 'Город'],
  ['street', 'Улица и дом'],
  ['zip', 'Индекс'],
];

function SignupWizard({ onSubmit }: SignupWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<SignupValues>(emptyValues);

  const update = (field: keyof SignupValues) => (event: React.ChangeEvent<HTMLInputElement>) => {
    const next = event.target.value;
    setValues((current) => ({ ...current, [field]: next }));
  };

  const isLast = step === steps.length - 1;

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        if (isLast) {
          onSubmit(values);
        } else {
          setStep((current) => Math.min(current + 1, steps.length - 1));
        }
      }}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '24px',
        maxWidth: '520px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxStepper steps={steps} current={step} />

      <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
        {step === 0 && (
          <>
            <JxInputField
              label="Имя"
              required
              value={values.name}
              onChange={update('name')}
              placeholder="Анна Петрова"
            />
            <JxInputField
              label="Электронная почта"
              type="email"
              required
              value={values.email}
              onChange={update('email')}
              helperText="Отправим письмо для подтверждения"
            />
            <JxInputField
              label="Телефон"
              type="tel"
              prefix="+7"
              value={values.phone}
              onChange={update('phone')}
              placeholder="900 000-00-00"
            />
          </>
        )}

        {step === 1 && (
          <>
            <JxInputField
              label="Город"
              required
              value={values.city}
              onChange={update('city')}
              placeholder="Москва"
            />
            <JxInputField
              label="Улица и дом"
              required
              value={values.street}
              onChange={update('street')}
              placeholder="Тверская, 12"
            />
            <JxInputField
              label="Индекс"
              value={values.zip}
              onChange={update('zip')}
              placeholder="125009"
            />
          </>
        )}

        {step === 2 && (
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(120px, 1fr) 2fr',
              gap: '12px 16px',
              margin: 0,
              padding: '16px',
              background: 'var(--jx-surface-2)',
              border: '1px solid var(--jx-rule)',
              borderRadius: 'var(--jx-r)',
            }}
          >
            {summaryLabels.map(([field, label]) => (
              <React.Fragment key={field}>
                <dt style={{ color: 'var(--jx-text-2)' }}>{label}</dt>
                <dd
                  style={{
                    margin: 0,
                    color: values[field] ? 'var(--jx-text)' : 'var(--jx-text-3)',
                    fontFamily: 'var(--jx-font-mono)',
                  }}
                >
                  {values[field] || '—'}
                </dd>
              </React.Fragment>
            ))}
          </dl>
        )}
      </div>

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton
          variant="ghost"
          type="button"
          disabled={step === 0}
          onClick={() => setStep((current) => Math.max(current - 1, 0))}
        >
          Назад
        </JxButton>
        <JxButton variant="primary" type="submit">
          {isLast ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

export default SignupWizard;

